//! Dependabot's rules (ADR 0019, contributing.md "Dependency updates"). Its npm cooldown is at least
//! pnpm's `minimumReleaseAge`, so it never proposes a version pnpm refuses to install. The files an
//! update leaves stale are regenerated by `dependabot-fixup.yml`, which runs the PR's packages and
//! so holds no secret. `dependabot-fixup-commit.yml` holds the release bot's token, executes
//! nothing from the PR and commits only the verified lockfile.

use super::{lines_of, repository_file};
use crate::doctor::GH_ACTIONS_LOCK_VERSION;

const DEPENDABOT: &str = include_str!("../../../../.github/dependabot.yml");
const PNPM_WORKSPACE: &str = include_str!("../../../../pnpm-workspace.yaml");
const FIXUP: &str = include_str!("../../../../.github/workflows/dependabot-fixup.yml");
const COMMIT: &str = include_str!("../../../../.github/workflows/dependabot-fixup-commit.yml");

/// pnpm 11's `minimumReleaseAge` when pnpm-workspace.yaml sets none: one day, in minutes.
const PNPM_DEFAULT_MINIMUM_RELEASE_AGE: u64 = 1440;

/// The paths the unprivileged workflow collects into its artifact.
const FIXUP_ALLOW_LIST: &str =
    "for path in .github/workflows/actions.lock apps/updates/src/generated/worker-configuration.d.ts; do";
/// The verified path the privileged workflow may commit.
const COMMIT_ALLOW_LIST: &str = "for path in .github/workflows/actions.lock; do";

/// The lines of `dependabot.yml`'s update entry for `ecosystem`.
fn update_entry(ecosystem: &str) -> Vec<&'static str> {
    let start = format!("  - package-ecosystem: {ecosystem}");
    DEPENDABOT
        .lines()
        .skip_while(|line| line.trim_end() != start)
        .enumerate()
        .take_while(|(i, line)| *i == 0 || !line.starts_with("  - package-ecosystem:"))
        .map(|(_, line)| line)
        .collect()
}

/// Every `*-days:` value of an update entry's cooldown.
fn cooldown_days(entry: &[&str]) -> Vec<u64> {
    entry
        .iter()
        .filter_map(|line| {
            let (key, value) = line.trim().split_once(':')?;
            key.ends_with("-days")
                .then(|| value.split('#').next().unwrap_or_default().trim().parse().ok())
                .flatten()
        })
        .collect()
}

/// pnpm's `minimumReleaseAge` in minutes: pnpm-workspace.yaml's, or pnpm's default.
fn pnpm_minimum_release_age(workspace: &str) -> u64 {
    workspace
        .lines()
        .find_map(|line| line.strip_prefix("minimumReleaseAge:"))
        .map_or(PNPM_DEFAULT_MINIMUM_RELEASE_AGE, |value| {
            value
                .split('#')
                .next()
                .unwrap_or_default()
                .trim()
                .parse()
                .unwrap_or_else(|_| {
                    panic!("pnpm-workspace.yaml's minimumReleaseAge isn't a number of minutes: {value}")
                })
        })
}

/// The lines of every `run: |` block among `lines`: those indented deeper than its `run:`.
fn script_lines<'a>(lines: &[&'a str]) -> Vec<&'a str> {
    let indent = |line: &str| line.len() - line.trim_start().len();
    let mut found = Vec::new();
    let mut block: Option<usize> = None;
    for line in lines {
        match block {
            Some(run) if line.trim().is_empty() || indent(line) > run => found.push(*line),
            _ => block = None,
        }
        if line.trim().trim_start_matches("- ") == "run: |" {
            block = Some(indent(line));
        }
    }
    found
}

#[test]
fn npm_cooldown_should_be_at_least_pnpms_minimum_release_age() {
    let days = cooldown_days(&update_entry("npm"));
    assert!(!days.is_empty(), "dependabot.yml's npm entry has no cooldown");
    let age = pnpm_minimum_release_age(PNPM_WORKSPACE);
    for value in days {
        assert!(
            value * 24 * 60 >= age,
            "a {value}-day npm cooldown is shorter than pnpm's minimumReleaseAge ({age} minutes)"
        );
    }
}

#[test]
fn cargo_and_npm_should_wait_the_two_weeks_the_repository_asks() {
    for ecosystem in ["cargo", "npm"] {
        assert_eq!(
            cooldown_days(&update_entry(ecosystem)),
            [14],
            "{ecosystem}: versions are added at least two weeks old"
        );
    }
}

#[test]
fn the_fixup_should_run_the_prs_packages_without_a_secret() {
    let job = lines_of(FIXUP, "jobs", "regenerate").join("\n");
    assert!(!FIXUP.contains("secrets."), "dependabot-fixup.yml must hold no secret");
    assert!(
        job.contains(
            "if: github.event.pull_request.user.login == 'dependabot[bot]' && github.actor == 'dependabot[bot]'"
        ),
        "only Dependabot's own pushes are regenerated"
    );
    assert!(
        job.contains("persist-credentials: false"),
        "the checkout keeps no token"
    );
    assert!(
        job.contains(&format!(
            "gh extension install github/gh-actions-lock --pin v{GH_ACTIONS_LOCK_VERSION}"
        )),
        "the fixup installs doctor.rs's GH_ACTIONS_LOCK_VERSION"
    );
    assert!(job.contains(FIXUP_ALLOW_LIST), "the fixup collects only the allow-list");
    let permissions: Vec<&str> = FIXUP
        .lines()
        .filter(|line| !line.starts_with(' ') && !line.starts_with('#'))
        .chain(lines_of(FIXUP, "jobs", "regenerate"))
        .filter(|line| line.contains("write"))
        .collect();
    assert!(
        permissions.is_empty(),
        "the fixup's token is read-only: {permissions:?}"
    );
}

#[test]
fn the_fixup_commit_should_run_nothing_from_the_pr() {
    let job = lines_of(COMMIT, "jobs", "commit").join("\n");
    for banned in [
        "actions/checkout",
        "pnpm",
        "uses: $/",
        "uses: ./",
        "git apply",
        "bash fixup",
    ] {
        assert!(
            !job.contains(banned),
            "the commit job holds the bot's token: no {banned}"
        );
    }
    for condition in ["workflows: [Dependabot fixup]", "types: [completed]"] {
        assert!(
            lines_of(COMMIT, "on", "workflow_run").join("\n").contains(condition),
            "missing trigger {condition}"
        );
    }
    for condition in [
        "github.event.workflow_run.conclusion == 'success'",
        "github.event.workflow_run.event == 'pull_request'",
        "github.event.workflow_run.actor.login == 'dependabot[bot]'",
        "github.event.workflow_run.head_repository.full_name == github.repository",
        "startsWith(github.event.workflow_run.head_branch, 'dependabot/')",
        "--field sha=\"$commit\" --field force=false",
        "parents: [$parent]",
    ] {
        assert!(job.contains(condition), "the commit job lacks {condition}");
    }
    assert!(
        job.contains(COMMIT_ALLOW_LIST),
        "the commit job reads only the verified lockfile"
    );
    assert!(
        !job.contains("for path in .github/workflows/actions.lock apps/updates/"),
        "the commit job must not promote unverified Wrangler types"
    );
    let scripts = script_lines(&lines_of(COMMIT, "jobs", "commit"));
    assert!(!scripts.is_empty(), "the commit job has no script");
    assert!(
        !scripts.iter().any(|line| line.contains("${{")),
        "event fields reach the scripts only through environment variables"
    );
    assert!(
        !COMMIT.lines().any(|line| line.trim() == "contents: write"),
        "the workflow's own token stays read-only; only the bot's writes"
    );
}

#[test]
fn the_fixup_commit_should_verify_the_lockfile_before_issuing_a_write_token() {
    let verification = COMMIT
        .find("- name: Verify regenerated actions.lock")
        .expect("the commit job verifies the lockfile");
    let token = COMMIT
        .find("- uses: actions/create-github-app-token@")
        .expect("the commit job issues a write token");
    let tree = COMMIT.find("tree='[]'").expect("the commit job builds a tree");
    assert!(
        verification < token && token < tree,
        "verify before issuing the token or building a tree"
    );
    let guard = &COMMIT[verification..token];
    let required = [
        "SHA: ${{ github.event.workflow_run.head_sha }}",
        "git -C \"$verify_dir\" fetch -q --depth=1",
        "(cd \"$verify_dir\" && gh actions-lock)",
        "cmp -s \"$verify_dir/.github/workflows/actions.lock\" \"$artifact\"",
    ];
    for required in required {
        assert!(guard.contains(required), "lockfile guard lacks {required}");
    }
    assert!(
        guard.contains(&format!(
            "gh extension install github/gh-actions-lock --pin v{GH_ACTIONS_LOCK_VERSION}"
        )),
        "the commit guard must use doctor.rs's pinned generator"
    );
}

#[test]
fn every_regenerated_path_should_exist() {
    let paths = FIXUP_ALLOW_LIST
        .trim_start_matches("for path in ")
        .trim_end_matches("; do")
        .split_whitespace();
    for path in paths {
        assert!(
            repository_file(path).is_some(),
            "the allow-list names a missing file: {path}"
        );
    }
}

#[test]
fn pnpm_minimum_release_age_should_read_the_setting_or_the_default() {
    assert_eq!(pnpm_minimum_release_age("packages:\n  - apps/*\n"), 1440);
    assert_eq!(
        pnpm_minimum_release_age("minimumReleaseAge: 20160 # two weeks\n"),
        20160
    );
}

#[test]
fn script_lines_should_stop_at_the_end_of_the_block() {
    let lines = [
        "      - run: |",
        "          echo $A",
        "",
        "          echo $B",
        "      - uses: x",
        "        with:",
        "          a: ${{ b }}",
    ];
    assert_eq!(script_lines(&lines), ["          echo $A", "", "          echo $B"]);
}

#[test]
fn cooldown_days_should_read_every_days_key_of_its_entry() {
    assert_eq!(cooldown_days(&update_entry("github-actions")), [7]);
    assert_eq!(
        cooldown_days(&[
            "    cooldown:",
            "      default-days: 14",
            "      semver-major-days: 30 # why"
        ]),
        [14, 30]
    );
}
